// Number parsing with suffixes
// Returns 0 on success, -1 on error (with message already printed via msg_error)
// On success, *result is set, *is_percent indicates if % suffix was used (for memlimit)
static int parse_size_suffix(const char *str, const char *optname_for_range, uint64_t min_val, uint64_t max_val, uint64_t *result, int allow_percent, int *is_percent) {
    // Skip leading spaces? Original trims leading spaces/tabs? Test with " 1MiB" succeeded. What about "\t1MiB"? Likely also. Use isspace.
    const char *p = str;
    while (*p && isspace((unsigned char)*p)) p++;
    if (is_percent) *is_percent = 0;
    // Check for empty or non-digit start (including -/+)
    if (*p == '\0') {
        msg_error("%s: Value is not a non-negative decimal integer", str);
        set_error();
        return -1;
    }
    if (!isdigit((unsigned char)*p)) {
        msg_error("%s: Value is not a non-negative decimal integer", str);
        set_error();
        return -1;
    }
    // Parse digits
    char *endptr;
    errno = 0;
    unsigned long long num = strtoull(p, &endptr, 10);
    if (errno == ERANGE) {
        // Overflow? What does original do for huge numbers? Test with 99999999999999999999999
        // For now, treat as range error? Or value error? Need to test.
        // Let's assume range error if optname given, else value error.
        // Actually need to test original with overflow.
        msg_error("%s: Value is not a non-negative decimal integer", str);
        set_error();
        return -1;
    }
    const char *suffix = endptr;
    // Handle suffix
    uint64_t mult = 1;
    int percent = 0;
    if (*suffix == '\0') {
        mult = 1;
    } else if (strcmp(suffix, "%") == 0) {
        if (!allow_percent) {
            msg_error("%s: Invalid multiplier suffix", suffix);
            fprintf(stderr, "%s: Valid suffixes are 'KiB' (2^10), 'MiB' (2^20), and 'GiB' (2^30).\n", progname);
            set_error();
            return -1;
        }
        percent = 1;
        if (is_percent) *is_percent = 1;
        // For percent, num must be in [1,100]? But range check will handle with optname%?
        // Don't apply mult.
    } else {
        // Check valid suffixes: K,M,G,k,m,g optionally + i/B
        // Valid: [KMGkmg], [KMGkmg]B, [KMGkmg]i, [KMGkmg]iB where B uppercase, i lowercase
        int valid = 0;
        char c0 = suffix[0];
        if (c0=='K'||c0=='M'||c0=='G'||c0=='k'||c0=='m'||c0=='g') {
            if (suffix[1]=='\0') valid=1;
            else if (suffix[1]=='B' && suffix[2]=='\0') valid=1;
            else if (suffix[1]=='i' && suffix[2]=='\0') valid=1;
            else if (suffix[1]=='i' && suffix[2]=='B' && suffix[3]=='\0') valid=1;
            else valid=0;
            if (valid) {
                if (c0=='K'||c0=='k') mult = 1024ULL;
                else if (c0=='M'||c0=='m') mult = 1024ULL*1024;
                else if (c0=='G'||c0=='g') mult = 1024ULL*1024*1024;
            }
        } else {
            valid=0;
        }
        if (!valid) {
            msg_error("%s: Invalid multiplier suffix", suffix);
            fprintf(stderr, "%s: Valid suffixes are 'KiB' (2^10), 'MiB' (2^20), and 'GiB' (2^30).\n", progname);
            set_error();
            return -1;
        }
    }
    if (percent) {
        *result = (uint64_t)num;
        // Range check for percent: [1,100] with optname% ?
        if (optname_for_range) {
            if (num < 1 || num > 100) {
                char tmp[256];
                snprintf(tmp, sizeof(tmp), "%s%%", optname_for_range);
                msg_error("Value of the option '%s' must be in the range [1, 100]", tmp);
                set_error();
                return -1;
            }
        }
        return 0;
    }
    // Check overflow for mult
    if (num != 0 && mult != 1) {
        if (num > UINT64_MAX / mult) {
            // Overflow: treat as range error?
            if (optname_for_range) {
                msg_error("Value of the option '%s' must be in the range [%" PRIu64 ", %" PRIu64 "]", optname_for_range, min_val, max_val);
            } else {
                msg_error("%s: Value is not a non-negative decimal integer", str);
            }
            set_error();
            return -1;
        }
    }
    uint64_t val = (uint64_t)num * mult;
    if (optname_for_range) {
        if (val < min_val || val > max_val) {
            msg_error("Value of the option '%s' must be in the range [%" PRIu64 ", %" PRIu64 "]", optname_for_range, min_val, max_val);
            set_error();
            return -1;
        }
    }
    *result = val;
    return 0;
}

// Simple uint32 parsing for threads etc. with range
static int parse_threads(const char *str, uint32_t *out) {
    uint64_t v;
    // threads allows suffixes, range [0,16384], optname 'threads'
    if (parse_size_suffix(str, "threads", 0, 16384, &v, 0, NULL) != 0) return -1;
    *out = (uint32_t)v;
    return 0;
}

static uint64_t physmem_value = 0;
static uint32_t cputhreads_value = 0;
static void init_hardware(void) {
    physmem_value = lzma_physmem();
    if (physmem_value == 0) physmem_value = 132386349056ULL; // fallback? Actually should be 0? But info-memory shows 0? No, if cannot detect, show 0? Let's use lzma value.
    cputhreads_value = lzma_cputhreads();
    if (cputhreads_value == 0) cputhreads_value = 1;
    // mt default is 25% of RAM? Or physmem/4? For 132386349056, /4 = 33096587264, matches. Good.
    // But what if physmem==0? Then default? Possibly 0? Let's compute.
    if (physmem_value == 0) mt_default_limit = 0;
    else mt_default_limit = physmem_value / 4;
    // Actually need to check: is it 25% rounded? For our case, exact division. Good.
    // Initialize mt limit to default (if not set)
    // memlimit_mt is 0 initially, meaning default. We'll keep 0 as "use default" and compute on demand.
}

static uint64_t get_mt_limit(void) {
    if (memlimit_mt_set) return memlimit_mt;
    if (memlimit_decompress_set && memlimit_decompress != 0) return memlimit_decompress;
    return mt_default_limit;
}
static uint64_t get_compress_limit(void) { return memlimit_compress; }
static uint64_t get_decompress_limit(void) { return memlimit_decompress; }

static void format_memlimit_info(uint64_t bytes, char *buf, size_t sz) {
    // Format as "Disabled" if 0, else "N MiB (B B)" where N is ceil(bytes / MiB)?
    // For 102400 B, shows 1 MiB. For 100 B, shows 1 MiB. For 0, Disabled.
    // For physmem display: "126254 MiB (132386349056 B)" where 126254 = ceil? 132386349056/1048576=126254 exactly? 126254*1048576=132386... Let's compute: 126254*1048576=132386... 126254*1048576 = 132386... Actually 132386349056/1048576=126254 exactly? 126254*1048576=132386... Let's trust.
    // For limits, same: ceil?
    if (bytes == 0) {
        snprintf(buf, sz, "Disabled");
    } else {
        uint64_t mib = (bytes + 1048576 - 1) / 1048576;
        // But for large values, need to handle? Use same.
        snprintf(buf, sz, "%" PRIu64 " MiB (%" PRIu64 " B)", mib, bytes);
    }
}

static void print_info_memory(void) {
    if (opt_robot) {
        // Format: physmem \t compress \t decompress \t mt \t default_for_T0 \t threads \n
        // compress/decompress 0 means disabled? For mt, show actual limit (default if not set)
        uint64_t comp = memlimit_compress; // 0 if disabled
