// Parse a single argv array (for env vars or CLI)
// For env vars, ignore non-options and handle -- as end for that array
// For CLI, collect files and handle -- as end for all
// Returns 0 on success, -1 on error (should exit 1)
// If help/version/info encountered, exits directly (not return)
static int parse_argv(int argc, char **argv, int is_env, int *end_of_options_flag) {
    int end_of_options = end_of_options_flag ? *end_of_options_flag : 0;
    for (int i=0;i<argc;i++) {
        char *arg=argv[i];
        if (end_of_options) {
            if (is_env) {
                // Ignore files in env
                continue;
            } else {
                add_input_file(arg);
                continue;
            }
        }
        if (arg[0]!='-' || arg[1]=='\0') {
            // File (including "-" alone)
            if (is_env) continue; // ignore files in env
            else add_input_file(arg);
        } else if (arg[1]=='-') {
            // Long option
            if (arg[2]=='\0') {
                // "--" alone
                end_of_options=1;
                if (end_of_options_flag) *end_of_options_flag=1;
                // For env, "--" ends that env's options (ignore rest of that env)
                if (is_env) {
                    // Ignore rest of this env array
                    break;
                }
                continue;
            }
            // Parse --name[=value]
            char *eq=strchr(arg,'=');
            char *name;
            char *value=NULL;
            size_t namelen;
            if (eq) {
                namelen=eq-(arg+2);
                name=malloc(namelen+1);
                memcpy(name,arg+2,namelen);
                name[namelen]='\0';
                value=eq+1;
            } else {
                name=strdup(arg+2);
                value=NULL;
            }
            // Find matches
            longopt_t *matches[64];
            int match_cnt=0, ambiguous=0;
            longopt_t *opt=find_longopt(name,&ambiguous,matches,&match_cnt);
            if (!opt) {
                if (ambiguous) {
                    // Build possibilities string in table order (matches already in table order? Our find_longopt collects in table order, good.)
                    // Format: "option '--%s' is ambiguous; possibilities: '--a' '--b' ..."
                    // Need to print with single quotes
                    // Use getopt_error_first for first line (always), then Try... if quiet==0
                    char buf[4096];
                    snprintf(buf,sizeof(buf),"option '--%s' is ambiguous; possibilities:",name);
                    // Append each possibility with " '--%s'"
                    for (int k=0;k<match_cnt;k++) {
                        char tmp[128];
                        snprintf(tmp,sizeof(tmp)," '--%s'",matches[k]->name);
                        if (strlen(buf)+strlen(tmp)<sizeof(buf)-1) strcat(buf,tmp);
                    }
                    getopt_error_first("%s",buf);
                    getopt_try_help();
                    free(name);
                    return -1;
                } else {
                    getopt_error_first("unrecognized option '--%s'",name);
                    getopt_try_help();
                    free(name);
                    return -1;
                }
            }
            // Found opt (exact or unique prefix)
            const char *full_name=opt->name;
            int has_arg=opt->has_arg;
            char *use_value=NULL;
            int need_next_arg=0;
            if (has_arg==NO_ARG) {
                if (value!=NULL) {
                    getopt_error_first("option '--%s' doesn't allow an argument",full_name);
                    getopt_try_help();
                    free(name);
                    return -1;
                }
            } else if (has_arg==REQ_ARG) {
                if (value!=NULL) {
                    use_value=value;
                } else {
                    // Need next argv as value
                    if (i+1>=argc) {
                        getopt_error_first("option '--%s' requires an argument",full_name);
                        getopt_try_help();
                        free(name);
                        return -1;
                    } else {
                        use_value=argv[i+1];
                        i++; // consume next
                    }
                }
            } else { // OPT_ARG
                if (value!=NULL) use_value=value;
                else use_value=NULL; // don't consume next
            }
            free(name);
            if (handle_longopt(opt->id, use_value, full_name)!=0) return -1;
        } else {
            // Short options cluster
            // For env, if arg is "-"? Already handled above (arg[1]=='\0' => file, ignored for env). Good.
            // Process each char in cluster
            size_t len=strlen(arg);
            for (size_t j=1;j<len;j++) {
                char c=arg[j];
                if (!short_is_valid(c)) {
                    getopt_error_first("invalid option -- '%c'",c);
                    getopt_try_help();
                    return -1;
                }
                if (c=='r') {
                    // Special: only Try... (no first line)
                    // handle_shortopt for 'r' will print Try... and exit. Call it.
                    handle_shortopt(c,NULL);
                    return -1; // not reached (exits)
                }
                if (short_requires_arg(c)) {
                    const char *val;
                    if (j+1<len) {
                        // Attached: rest of cluster as value (including '='? For -S=.foo, rest is "=.foo", value "=.foo". Good.)
                        val=arg+j+1;
