int main(int argc, char **argv) {
    const char *filename=argv[1];
    FILE *f=fopen(filename,"rb");
    fseek(f,0,SEEK_END);
    long fsize=ftell(f);
    fseek(f,0,SEEK_SET);
    uint8_t *data=malloc(fsize);
    fread(data,1,fsize,f);
    fclose(f);
    printf("fsize %ld\n",fsize);
    printf("header %02x %02x %02x %02x %02x %02x\n",data[0],data[1],data[2],data[3],data[4],data[5]);
    printf("footer %02x %02x\n",data[fsize-2],data[fsize-1]);
    uint32_t backward = data[fsize-8] | (data[fsize-7]<<8) | (data[fsize-6]<<16) | (data[fsize-5]<<24);
    printf("backward %u\n",backward);
    uint64_t index_size=((uint64_t)backward+1)*4;
    printf("index_size %llu\n",(unsigned long long)index_size);
    uint64_t index_start=fsize-12-index_size;
    printf("index_start %llu\n",(unsigned long long)index_start);
    lzma_index *idx=NULL;
    size_t in_pos=0;
    uint64_t memlimit=UINT64_MAX;
    lzma_ret r=lzma_index_buffer_decode(&idx,&memlimit,NULL,data+index_start,&in_pos,(size_t)index_size);
    printf("index decode ret %d in_pos %zu\n",r,in_pos);
    if(r==LZMA_OK) {
        printf("blocks %llu uncomp %llu\n",(unsigned long long)lzma_index_block_count(idx),(unsigned long long)lzma_index_uncompressed_size(idx));
        lzma_index_iter iter;
        lzma_index_iter_init(&iter,idx);
        if(lzma_index_iter_next(&iter,LZMA_INDEX_ITER_BLOCK)) {
            printf("block unpadded %llu uncomp %llu\n",(unsigned long long)iter.block.unpadded_size,(unsigned long long)iter.block.uncompressed_size);
        }
        lzma_index_end(idx,NULL);
    }
    // block header
    lzma_block block;
    memset(&block,0,sizeof(block));
    block.version=0;
    block.check=LZMA_CHECK_CRC64;
    lzma_filter dec_filters[LZMA_FILTERS_MAX+1];
    block.filters=dec_filters;
    block.header_size=lzma_block_header_size_decode(data[12]);
    printf("header size byte %02x => size %u\n",data[12],block.header_size);
    r=lzma_block_header_decode(&block,NULL,data+12);
    printf("block header decode ret %d\n",r);
    if(r==LZMA_OK) {
        printf("compressed_size %llu uncompressed_size %llu\n",(unsigned long long)block.compressed_size,(unsigned long long)block.uncompressed_size);
        for(int i=0;block.filters[i].id!=LZMA_VLI_UNKNOWN;i++) {
            printf("filter %d id %llx\n",i,(unsigned long long)block.filters[i].id);
            if(block.filters[i].id==LZMA_FILTER_LZMA2) {
                lzma_options_lzma *o=block.filters[i].options;
                printf(" lzma2 dict %u\n",o->dict_size);
            }
        }
        for(int i=0;block.filters[i].id!=LZMA_VLI_UNKNOWN;i++) free(block.filters[i].options);
    }
    free(data);
    return 0;
}
